<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES);$editing=!empty($report['id']);$groups=['Course identity'=>['course_code'=>'Course code','course_title'=>'Course title','academic_year'=>'Academic year','semester'=>'Semester','course_coordinator'=>'Course coordinator','course_instructors'=>'Course instructors','department_name'=>'Department','program_name'=>'Program','college_name'=>'College','institution_name'=>'Institution','location'=>'Location','number_of_sections'=>'Number of sections','report_version'=>'Report version'],'Student results'=>['students_enrolled'=>'Students enrolled','students_starting'=>'Students starting','students_completed'=>'Students completed','students_passed'=>'Students passed','students_failed'=>'Students failed'],'Evaluation and improvement'=>['clo_achievement_summary'=>'CLO achievement summary','assessment_summary'=>'Assessment summary','teaching_summary'=>'Teaching summary','student_feedback_summary'=>'Student feedback summary','course_improvement_actions'=>'Course improvement actions','general_notes'=>'General notes']];$long=array_flip(['course_instructors','clo_achievement_summary','assessment_summary','teaching_summary','student_feedback_summary','course_improvement_actions','general_notes']);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$editing?'Edit':'Create'?> course report</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:950px;margin:auto;padding:1rem}fieldset{margin:1rem 0;padding:1rem}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.field label{display:block;font-weight:700}.field input,.field select,.field textarea{width:100%;box-sizing:border-box;padding:.55rem}textarea{min-height:7rem}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main><h1><?=$editing?'Edit':'Create'?> course report</h1><?php if($errors):?><div role="alert"><h2>Please correct the following</h2><ul><?php foreach($errors as$e):?><li><?=$h($e)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><?=csrfField()?><fieldset><legend>Linked specification and workflow</legend><div class="grid"><div class="field"><label for="course_specification_id">Course specification</label><select id="course_specification_id" name="course_specification_id"><option value="">Manual entry</option><?php foreach($specifications as$s):?><option value="<?=(int)$s['id']?>" <?=((int)($report['course_specification_id']??0)===(int)$s['id'])?'selected':''?>><?=$h($s['course_code'].' — '.$s['course_title'])?></option><?php endforeach;?></select></div><div class="field"><label for="report_date">Report date</label><input id="report_date" type="date" name="report_date" value="<?=$h($report['report_date']??'')?>"></div><div class="field"><label for="status">Status</label><select id="status" name="status"><?php foreach(['Draft','Under Review','Approved','Completed']as$v):?><option <?=($report['status']??'Draft')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div></div></fieldset><?php foreach($groups as$legend=>$fields):?><fieldset><legend><?=$legend?></legend><div class="grid"><?php foreach($fields as$name=>$label):?><div class="field"><label for="<?=$name?>"><?=$label?></label><?php if(isset($long[$name])):?><textarea id="<?=$name?>" name="<?=$name?>"><?=$h($report[$name]??'')?></textarea><?php else:?><input id="<?=$name?>" name="<?=$name?>" <?=$name==='course_code'||$name==='course_title'||$name==='academic_year'||$name==='semester'?'required':''?> <?=$name==='students_enrolled'||str_starts_with($name,'students_')?'type="number" min="0" max="100000"':''?> value="<?=$h($report[$name]??'')?>"><?php endif;?></div><?php endforeach;?></div></fieldset><?php endforeach;?><button>Save course report</button> <a href="/course-reports">Cancel</a></form></main></body></html>
